// Login: the backdrop must sit behind the form, so the form controls stay usable.
const signIn = page.getByRole('button', { name: /sign in|log in|continue/i }).first();
await expect(signIn).toBeVisible();
const backdrop = page.locator('[class*="backdrop" i], [data-testid*="backdrop" i]').first();
await expect(backdrop).toHaveCount(1);
const bz = await backdrop.evaluate((el) => getComputedStyle(el).zIndex);
const fz = await signIn.evaluate((el) => {
  let n = el;
  while (n) {
    const z = getComputedStyle(n).zIndex;
    if (z !== 'auto') return z;
    n = n.parentElement;
  }
  return '0';
});
expect(Number(bz === 'auto' ? 0 : bz)).toBeLessThan(Number(fz));
// the sign-in control must receive the click (not covered by the backdrop)
await signIn.click({ trial: true, timeout: 3000 });

// Ops map: the controls must be reachable and not covered by other layers.
