// Login: nothing (e.g. the backdrop) may stack above the sign-in controls.
await page.goto('/login');
const signIn = page.getByRole('button', { name: /sign in|log in|continue/i }).first();
await expect(signIn).toBeVisible();
const loginOnTop = await signIn.evaluate((el) => {
  const r = el.getBoundingClientRect();
  const top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
  return !!top && (el === top || el.contains(top) || top.contains(el));
});
expect(loginOnTop).toBe(true);

// Ops map: the map controls must stack above the map layers.
